1	package shadow
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"time"
7	)
8	
9	// BatchDevice 是批量修改期望配置中单台设备的请求项。
10	type BatchDevice struct {
11		DeviceID string
12		// Revision 是调用方已读取的期望修订号，必须等于设备当前修订号。
13		Revision uint64
14		// Config 是完整替换期望配置的 JSON 对象。
15		Config json.RawMessage
16	}
17	
18	// BatchRecord 是一次成功提交的批量修改记录。
19	type BatchRecord struct {
20		RequestID string
21		Operator  string
22		Time      time.Time
23		// Revisions 是各设备本次修改产生的新修订号，按设备标识索引。
24		Revisions map[string]uint64
25	}
26	
27	// batchRequestState 是已成功批量请求的内部记录，用于去重与查询。
28	type batchRequestState struct {
29		ID       string
30		Operator string
31		Time     time.Time
32		// Devices 按首次提交的次序保存。
33		Devices []batchDeviceState
34	}
35	
36	type batchDeviceState struct {
37		DeviceID string
38		// Revision 是提交时已读取的修订号。
39		Revision uint64
40		// NewRevision 是本次修改产生的新修订号。
41		NewRevision uint64
42		Config      json.RawMessage
43	}
44	
45	// BatchUpdateDesired 用一次请求同时修改多台已登记设备的期望配置，
46	// 每台设备完整替换旧配置、修订号各加一并留下带同一请求标识的审计。
47	//
48	// 请求标识在当前存储内唯一：相同标识再次提交相同内容（设备次序、JSON
49	// 空白与对象字段顺序无关，数字按数值比较，时间按同一时刻判断）直接返回
50	// 首次结果，不重复修改；相同标识提交不同内容返回 ErrRequestConflict，
51	// 原结果保持有效。任一设备校验失败（列表为空、标识为空或重复、设备未
52	// 登记、配置非法、修订号冲突）时整批报错，所有设备状态、审计均不变，
53	// 也不占用请求标识。离线设备同样接受修改。
54	func (s *Store) BatchUpdateDesired(requestID, operator string, at time.Time, devices []BatchDevice) (BatchRecord, error) {
55		s.mu.Lock()
56		defer s.mu.Unlock()
57		if err := s.checkOpen(); err != nil {
58			return BatchRecord{}, err
59		}
60		if requestID == "" {
61			return BatchRecord{}, ErrInvalidRequestID
62		}
63		if operator == "" {
64			return BatchRecord{}, ErrInvalidOperator
65		}
66		if at.IsZero() {
67			return BatchRecord{}, ErrInvalidTime
68		}
69		if len(devices) == 0 {
70			return BatchRecord{}, ErrInvalidDeviceList
71		}
72		// 先校验并复制全部输入，再决定是否落库；任何一步失败都不改变状态。
73		type prepared struct {
74			dev *deviceState
75			id  string
76			rev uint64
77			cfg json.RawMessage
78		}
79		items := make([]prepared, 0, len(devices))
80		seen := make(map[string]bool, len(devices))
81		for _, bd := range devices {
82			if bd.DeviceID == "" {
83				return BatchRecord{}, ErrInvalidDeviceID
84			}
85			if seen[bd.DeviceID] {
86				return BatchRecord{}, fmt.Errorf("%w: %s", ErrDuplicateDevice, bd.DeviceID)
87			}
88			seen[bd.DeviceID] = true
89			d, ok := s.devices[bd.DeviceID]
90			if !ok {
91				return BatchRecord{}, fmt.Errorf("%w: %s", ErrDeviceNotFound, bd.DeviceID)
92			}
93			cfg, err := validateConfig(bd.Config)
94			if err != nil {
95				return BatchRecord{}, err
96			}
97			items = append(items, prepared{dev: d, id: bd.DeviceID, rev: bd.Revision, cfg: cfg})
98		}
99		// 已成功的请求标识：内容一致直接返回首次结果（即使设备此后已有新
100		// 修改，也不用旧请求覆盖）；内容不同返回可区分的冲突错误。
101		if rec, ok := s.batches[requestID]; ok {
102			if rec.matches(operator, at, devices) {
103				return rec.record(), nil
104			}
105			return BatchRecord{}, fmt.Errorf("%w: %s", ErrRequestConflict, requestID)
106		}
107		// 修订号冲突检查在任何修改之前完成，失败整批不变。
108		for _, it := range items {
109			if it.rev != it.dev.Revision {
110				return BatchRecord{}, fmt.Errorf("%w: device %s want %d, got %d",
111					ErrRevisionConflict, it.id, it.dev.Revision, it.rev)
112			}
113		}
114		rec := &batchRequestState{ID: requestID, Operator: operator, Time: at}
115		err := s.commit(func() error {
116			for _, it := range items {
117				d := it.dev
118				before := d.Desired
119				d.Desired = it.cfg
120				d.Revision++
121				d.Audit = append(d.Audit, AuditRecord{
122					DeviceID:  it.id,
123					Operator:  operator,
124					Time:      at,
125					Revision:  d.Revision,
126					RequestID: requestID,
127					Before:    cloneRaw(before),
128					After:     cloneRaw(it.cfg),
129				})
130				d.refreshDiff(at)
131				rec.Devices = append(rec.Devices, batchDeviceState{
132					DeviceID:    it.id,
133					Revision:    it.rev,
134					NewRevision: d.Revision,
135					Config:      cloneRaw(it.cfg),
136				})
137			}
138			s.batches[requestID] = rec
139			return nil
140		})
141		if err != nil {
142			return BatchRecord{}, err
143		}
144		return rec.record(), nil
145	}
146	
147	// GetBatchRequest 按请求标识查询成功提交的批量修改记录。
148	// 标识为空返回 ErrInvalidRequestID；未知标识（含从未成功提交的请求）
149	// 返回 ErrRequestNotFound。返回的数据是独立副本。
150	func (s *Store) GetBatchRequest(requestID string) (BatchRecord, error) {
151		s.mu.Lock()
152		defer s.mu.Unlock()
153		if err := s.checkOpen(); err != nil {
154			return BatchRecord{}, err
155		}
156		if requestID == "" {
157			return BatchRecord{}, ErrInvalidRequestID
158		}
159		rec, ok := s.batches[requestID]
160		if !ok {
161			return BatchRecord{}, fmt.Errorf("%w: %s", ErrRequestNotFound, requestID)
162		}
163		return rec.record(), nil
164	}
165	
166	// matches 判断重新提交的请求内容是否与首次成功提交一致。
167	// 设备次序无关；配置按语义比较（忽略空白与对象字段顺序，数字按数值，
168	// 数组有序，字段缺失与 null 不同）；时间按同一时刻判断。
169	func (r *batchRequestState) matches(operator string, at time.Time, devices []BatchDevice) bool {
170		if r.Operator != operator || !r.Time.Equal(at) || len(r.Devices) != len(devices) {
171			return false
172		}
173		byID := make(map[string]batchDeviceState, len(r.Devices))
174		for _, d := range r.Devices {
175			byID[d.DeviceID] = d
176		}
177		for _, bd := range devices {
178			d, ok := byID[bd.DeviceID]
179			if !ok || d.Revision != bd.Revision || !rawEqual(d.Config, bd.Config) {
180				return false
181			}
182		}
183		return true
184	}
185	
186	// record 生成批量记录的独立副本。
187	func (r *batchRequestState) record() BatchRecord {
188		revisions := make(map[string]uint64, len(r.Devices))
189		for _, d := range r.Devices {
190			revisions[d.DeviceID] = d.NewRevision
191		}
192		return BatchRecord{
193			RequestID: r.ID,
194			Operator:  r.Operator,
195			Time:      r.Time,
196			Revisions: revisions,
197		}
198	}
