	}
	if err := s.SetOffline("ghost"); !errors.Is(err, ErrDeviceNotFound) {
		t.Fatalf("SetOffline: %v", err)
	}
	if _, err := s.Diff("ghost"); !errors.Is(err, ErrDeviceNotFound) {
		t.Fatalf("Diff: %v", err)

