package shadow

import (
	"bytes"
	"encoding/json"
	"io"
	"testing"
)

func TestScratchDecoder(t *testing.T) {
	cases := []struct {
		raw    string
		object bool
	}{
		{`{"mode":"auto"}`, true},
		{" \t\n{\"mode\":\"auto\"}\r\n ", true},
		{`{}`, true},
		{`{"a":{"b":1},"arr":[1,2]}`, true},
		{`{"s":"} { not end"}`, true},
		{`{"s":"{} null"}`, true},
		{`{"mode":"auto"} null`, false},
		{`{"mode":"auto"} {}`, false},
		{`{"mode":"auto"} 1`, false},
		{`{"mode":"auto"}"x"`, false},
		{`{"mode":"auto"}garbage`, false},
		{`{"mode":"auto"} `, true},
		{`null`, false},
		{`[1]`, false},
		{``, false},
		{`{"a":1`, false},
		{` {"a":1} `, true},
	}
	for _, c := range cases {
		_, ok := decodeObject(json.RawMessage(c.raw))
		if ok != c.object {
			t.Errorf("decodeObject(%q) = %v, want %v", c.raw, ok, c.object)
		}
	}
	// rawEqual strictness
	if rawEqual(json.RawMessage(`{"a":1}`), json.RawMessage(`{"a":1} null`)) {
		t.Error("rawEqual should reject trailing")
	}
	if !rawEqual(json.RawMessage(`{"a":1}`), json.RawMessage(`{ "a": 1 } `)) {
		t.Error("rawEqual should ignore whitespace")
	}
	// Demonstrate Decoder behavior the fix relies on.
	for _, tail := range []string{" null", " {}", " xyz", ""} {
		dec := json.NewDecoder(bytes.NewReader([]byte(`{"a":1}` + tail)))
		var v any
		if err := dec.Decode(&v); err != nil {
			t.Fatalf("first decode: %v", err)
		}
		var extra json.RawMessage
		err := dec.Decode(&extra)
		t.Logf("tail=%q second-decode err=%v (io.EOF=%v)", tail, err, err == io.EOF)
	}
}

