package shadow

import "os"

func readFile(p string) ([]byte, error) { return os.ReadFile(p) }
func readFileBytes(t interface{ Helper() }, p string) []byte {
	t.Helper()
	b, err := os.ReadFile(p)
	if err != nil { t.Fatalf("read: %v", err) }
	return b
}
func writeFileBytes(t interface{ Helper() }, p string, b []byte) {
	t.Helper()
	if err := os.WriteFile(p, b, 0o644); err != nil { t.Fatalf("write: %v", err) }
}
func injectTrailing(b []byte) []byte {
	// reported config appears as "reported\":{}" on disk.
	needle := []byte(`"reported":{}`)
	i := indexBytes(b, needle)
	if i < 0 { return b }
	at := i + len(needle) - 1 // position of closing }
	res := append([]byte{}, b[:at]...)
	res = append(res, []byte(`} null`)...)
	res = append(res, b[at+1:]...)
	return res
}
func indexBytes(s, sub []byte) int {
	for i := 0; i+len(sub) <= len(s); i++ {
		if string(s[i:i+len(sub)]) == string(sub) { return i }
	}
	return -1
}
